extern "C" int ls3_dots(const int8_t*x,const int8_t*w,int N,int K,int R,int32_t*out){try{need(environment(),"FFI environment");for(int i=0;i<N;++i)for(int j=0;j<R;++j)out[size_t(i)*R+j]=exact_dot(x+size_t(i)*K,w+size_t(j)*K,K);return 0;}catch(...){return 1;}}
extern "C" int ls3_fma(const float*x,const void*w,int N,int K,int R,int bytes,float*out){try{need(environment()&&(bytes==1||bytes==4),"FFI FMA environment/type");for(int i=0;i<N;++i)for(int j=0;j<R;++j)out[size_t(i)*R+j]=bytes==1?fma_dot(x+size_t(i)*K,(const int8_t*)w+size_t(j)*K,K):fma_dot(x+size_t(i)*K,(const float*)w+size_t(j)*K,K);return 0;}catch(...){return 1;}}
extern "C" int ls3_quant(const float*x,int N,int K,int8_t*q,float*s){try{need(environment(),"FFI quant environment");for(int i=0;i<N;++i)s[i]=quantize(x+size_t(i)*K,K,q+size_t(i)*K);return 0;}catch(...){return 1;}}
extern "C" int ls3_projection(const float*x,const float*w,int N,int K,int R,float*out){try{need(environment(),"FFI P environment");for(int i=0;i<N;++i)for(int j=0;j<R;++j)out[size_t(i)*R+j]=projection_dot(x+size_t(i)*K,w+size_t(j)*K,K);return 0;}catch(...){return 1;}}
