template<class T>static std::vector<T> array(const json&j){need(j.at("itemsize")==sizeof(T),"typed export itemsize");size_t n=1;for(auto v:j.at("shape")){int64_t d=v;need(d>=0&&d<100000000,"typed export dimension");n*=size_t(d);need(n<1000000000,"typed export maximum");}need(j.at("bytes")==n*sizeof(T),"typed export bytes");std::ifstream f(j.at("path").get<std::string>(),std::ios::binary);need(bool(f),"typed export open");std::vector<T>v(n);f.read((char*)v.data(),n*sizeof(T));need(size_t(f.gcount())==n*sizeof(T)&&f.peek()==EOF,"typed export short/extra bytes");return v;}
static W8 weight(const json&j){W8 w;w.rows=j.at("rows");w.cols=j.at("cols");w.q=array<int8_t>(j.at("q"));w.s=array<float>(j.at("s"));need(w.q.size()==size_t(w.rows)*w.cols&&w.s.size()==size_t(w.rows),"W8 shape");for(float s:w.s)need(std::isfinite(s)&&s>0,"W8 scales");return w;}
static Layer layer(const json&j){Layer l;l.H=j.at("H");l.K=j.at("K");l.layer=j.at("layer");need(l.H>0&&l.H<=2048&&(l.K==6||l.K==8),"layer adapter");l.normals=array<float>(j.at("normals"));l.means=array<float>(j.at("means"));l.P=array<float>(j.at("P"));l.thresholds=array<double>(j.at("thresholds"));need(l.normals.size()==size_t(31)*l.H&&l.means.size()==size_t(32)*l.H&&l.P.size()==size_t(128)*l.H&&l.thresholds.size()==31,"geometry shape");
 for(auto v:j.at("operators")){Operator o;o.expert=v.at("expert");o.I=v.at("I");o.global=v.at("global");o.g=weight(v.at("gate"));o.u=weight(v.at("up"));o.down=weight(v.at("down"));need(o.g.rows==o.I&&o.u.rows==o.I&&o.g.cols==l.H&&o.u.cols==l.H&&o.down.rows==l.H&&o.down.cols==o.I,"GU Down shape closure");o.cq=array<int8_t>(v.at("cq"));o.cs=array<float>(v.at("cs"));o.cb=array<float>(v.at("cb"));o.bq=array<int8_t>(v.at("bq"));o.bs=array<float>(v.at("bs"));o.uq=array<int8_t>(v.at("uq"));o.us=array<float>(v.at("us"));o.db=array<float>(v.at("db"));o.Q=v.at("Q");need(o.cq.size()==size_t(32)*l.H*128&&o.cs.size()==size_t(32)*l.H&&o.cb.size()==o.cs.size(),"C shape");need(o.bq.size()==size_t(o.global?1:32)*o.Q*(o.global?l.H:128)&&o.bs.size()==size_t(o.global?1:32)*o.Q&&o.uq.size()==size_t(l.H)*o.Q&&o.us.size()==size_t(l.H)&&o.db.size()==size_t(32)*l.H,"D exact stored factor shape");for(int c:v.at("unsupported"))o.unsupported.at(c)=true;for(int c:v.at("dunsupported"))o.dunsupported.at(c)=true;
  if(v.contains("ng")){o.ng=array<float>(v.at("ng"));o.nu=array<float>(v.at("nu"));o.gb=array<float>(v.at("gb"));o.ub=array<float>(v.at("ub"));o.yb=array<float>(v.at("yb"));need(o.ng.size()==size_t(o.I)*128&&o.nu.size()==o.ng.size()&&o.gb.size()==size_t(32)*o.I&&o.ub.size()==o.gb.size()&&o.yb.size()==size_t(32)*l.H,"NL shape");}l.ops.push_back(std::move(o));}
 need(l.ops.size()==2,"two templates per pilot layer");return l;
}
static uint64_t resident(const Layer&l){uint64_t n=(l.normals.size()+l.means.size()+l.P.size())*4+l.thresholds.size()*8;for(auto&o:l.ops){for(auto*w:{&o.g,&o.u,&o.down})n+=w->q.size()+w->s.size()*4;n+=o.cq.size()+o.bq.size()+o.uq.size();for(auto*v:{&o.cs,&o.cb,&o.bs,&o.us,&o.db,&o.ng,&o.nu,&o.gb,&o.ub,&o.yb})n+=v->size()*4;}return n;}
