 std::vector<uint8_t>eviction(size_t(1)<<30,0);std::array<uint64_t,8>touches{};double eviction_seconds=0;auto evict=[&]{auto t=Clock::now();team.run([&](int id){volatile uint8_t*p=eviction.data()+(size_t(id)<<27);uint64_t n=0;for(size_t j=0;j<(size_t(1)<<27);j+=64){p[j]=uint8_t(p[j]+1);++n;}touches[id]+=n;});eviction_seconds+=seconds(t);};
